import React from 'react';
import { Form, Input, Button, Switch, Select } from 'antd';
import { StdItemEdit, IProps, IState } from '../../part/StdItemEdit';
import { staffApi } from '../../api/console/staff';
import { staffRoleApi } from '../../api/console/staff.role';
import Configure from '../../api/Configure';

interface ThisState extends IState {
    roleOpt: any[],
}

export default class StaffEdit extends StdItemEdit<IProps, ThisState> {

    state = {
        ...super.buildInitState(),
        roleOpt: [] as any[],
    }

    constructor(props: IProps, context: any) {
        super(props, context);
        staffRoleApi.optionList().then(d => this.setState({ roleOpt: d }))
    }

    renderForm() {
        const { createMode, item } = this.state;
        console.log("拿到的item=", item);
        const roleOptUi: any[] = [];
        const { roleOpt } = this.state;
        roleOpt.forEach(opt => {
            roleOptUi.push(<Select.Option value={opt.value} key={opt.value}>{opt.label}</Select.Option>);
        })
        return (
            <Form 
                labelCol={{ span: 4 }}
                wrapperCol={{ span: 20 }}
                name="basic"
                initialValues={item}
                onFinish={this.onFormFinish}
                onFinishFailed={this.onFormFinishFailed}
            >
                <Form.Item label={Configure.Gl(1055,"ID")} name="id">
                    <Input disabled />
                </Form.Item>
                <Form.Item label={Configure.Gl(1308,"用户名")} name="username">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1534,"昵称")} name="nickname">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1309,"密码")} name="password">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1535,"管理员")} name="admin" valuePropName="checked">
                    <Switch />
                </Form.Item>
                <Form.Item label={Configure.Gl(1000,"角色")} name="roleId">
                    <Select>{roleOptUi}</Select>
                </Form.Item>
                <Form.Item label={Configure.Gl(1536,"所属部门")} name="dept">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1537,"所属公司")} name="company">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1065,"备注")} name="note">
                    <Input />
                </Form.Item>
                <Form.Item wrapperCol={{ offset: 4, span: 16 }}>
                    <Button type="primary" htmlType="submit"> {createMode ? Configure.Gl(1387,"保存新增")  : Configure.Gl(1388,"保存编辑")} </Button>
                </Form.Item>
            </Form>
        );
    }


    onFormFinish = (values: any) => {
        console.log('onFormFinish:', values);
        //if(true) return;
        const { createMode } = this.state;
        if (createMode) {
            staffApi.create(values).then(d => {
                this.setState({ visible: false });
                this.props.reload();
            });
        } else {
            staffApi.update(values).then(d => {
                this.setState({ visible: false });
                this.props.reload();
            })
        }
    }

}