import React from 'react';
import { Form, Input, Button } from 'antd';
import { StdItemEdit, IProps, IState } from '../../part/StdItemEdit';
import { platformAppApi } from '../../api/console/platform.app';
import Configure from '../../api/Configure';

export default class PlatformAppEdit extends StdItemEdit<IProps, IState> {

    state = {
        ...super.buildInitState(),
    }

    renderForm() {
        const { createMode, item } = this.state;
        console.log("拿到的item=", item);
        return (
            <Form 
                labelCol={{ span: 10 }}
                wrapperCol={{ span: 20 }}
                name="basic"
                initialValues={item}
                onFinish={this.onFormFinish}
                onFinishFailed={this.onFormFinishFailed}
            >
                <Form.Item label={Configure.Gl(1055,"ID")} name="id">
                    <Input disabled />
                </Form.Item>
                <Form.Item label={Configure.Gl(1384,"应用名称")} name="name">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1122,'平台编码')} name="platformCode">
                    <Input />
                </Form.Item>
                <Form.Item label="GameId" name="gameId">
                    <Input />
                </Form.Item>
                <Form.Item label="GameKey" name="gameKey">
                    <Input />
                </Form.Item>
                <Form.Item label="SecretKey" name="secretKey">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1385,"关联编码")} name="associatedCode">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1386,'客户端路径')} name="clientPath">
                    <Input />
                </Form.Item>
                <Form.Item label={Configure.Gl(1065,"备注")} name="note">
                    <Input />
                </Form.Item>
                <Form.Item wrapperCol={{ offset: 4, span: 16 }}>
                    <Button type="primary" htmlType="submit"> {createMode ? Configure.Gl(1387,"保存新增") : Configure.Gl(1388,"保存编辑")} </Button>
                </Form.Item>
            </Form>
        );
    }


    onFormFinish = (values: any) => {
        console.log('onFormFinish:', values);
        //if(true) return;
        const { createMode } = this.state;
        if (createMode) {
            platformAppApi.create(values).then(d => {
                this.setState({ visible: false });
                this.props.reload();
            });
        } else {
            platformAppApi.update(values).then(d => {
                this.setState({ visible: false });
                this.props.reload();
            })
        }
    }

}