import React, { RefObject } from 'react';
import { RouteComponentProps } from 'react-router-dom';
import { Button, Table, Space, Divider, Modal } from 'antd';
import { SearchOutlined, PlusOutlined, ExclamationCircleOutlined } from '@ant-design/icons';
import { TablePaginationConfig, ColumnsType } from 'antd/lib/table/Table';

import { HomeLayout } from '../../layout/HomeLayout';
import { RoutePath } from '../../route/path';
import { cloudDeivceApi } from '../../api/console/cloud.device';
import CloudDeviceEdit from './CloudDeviceEdit';
import CloudDeviceTimeChanger from './CloudDeviceTimeChanger';
import Configure from '../../api/Configure';

export default class CloudMongoIndex extends React.Component<RouteComponentProps> {

    private editor: RefObject<CloudDeviceEdit>;
    private timeChanger: RefObject<CloudDeviceTimeChanger>;

    constructor(props: RouteComponentProps) {
        super(props);
        this.editor = React.createRef();
        this.timeChanger = React.createRef();
    }

    state = {
        showEdit: false,
        itemList: [],
    };

    getCols(): ColumnsType<any> {
        return [
            {
                title: Configure.Gl(1055,'ID'),
                dataIndex: 'id',
                width: 80,
                fixed: 'left',
                sorter: (a, b) => a.id - b.id,
            },
            { title: Configure.Gl(1056,'编码'), dataIndex: 'code', fixed: 'left', width: 120 },
            { title: Configure.Gl(1058,'服务器名'), dataIndex: 'name', width: 140 },
            { title: Configure.Gl(1059,'内网地址'), dataIndex: ['host', 'LAN'], width: 130 },
            { title: Configure.Gl(1060,'外网地址'), dataIndex: ['host', 'WAN'], width: 130 },
            { title: Configure.Gl(1061,'域名'), dataIndex: ['host', 'domain'], width: 210 },
            {
                title: Configure.Gl(1057,'操作'),
                width: 280,
                render: (value: any, record: any, index: number) => {
                    return (<Space>
                        <Button onClick={() => this.timeChanger.current?.show(record)}>{Configure.Gl(1135,'修改时间')}</Button>
                        <Button type="primary" onClick={() => this.editor.current?.showUpdate(record)}>{Configure.Gl(1117,'编辑')}</Button>
                        <Button danger onClick={() => this.deleteItem(record)}>{Configure.Gl(1133,'删除')}</Button>
                    </Space>);
                },
            },
            { title: Configure.Gl(1062,'SSH端口'), dataIndex: ['ssh', 'port'], width: 100 },
            { title: Configure.Gl(1063,'SSH用户名'), dataIndex: ['ssh', 'user'], width: 120 },
            { title: Configure.Gl(1064,'SSH密码'), dataIndex: ['ssh', 'password'], width: 240 },
            { title: Configure.Gl(1065,'备注'), dataIndex: 'name', width: 330 },
        ];
    }

    render() {
        const columns = this.getCols();

        const pagination: TablePaginationConfig = {
            showSizeChanger: true,
            showQuickJumper: true,
        };

        return (
            <HomeLayout path={RoutePath.CLOUD_DEVICE_INDEX}>
                <Space>
                    <Button type="primary" icon={<PlusOutlined />} onClick={() => this.editor.current?.showCreate()}>{Configure.Gl(1389,'新增')}</Button>
                    <Button type="primary" icon={<SearchOutlined />} onClick={() => this.reload()}>{Configure.Gl(1152,'查找')}</Button>
                </Space>
                <Divider />
                <Table dataSource={this.state.itemList} columns={columns} pagination={pagination} scroll={{ x: 1500, y: 512 }} />
                <CloudDeviceEdit ref={this.editor} reload={() => this.reload()} ></CloudDeviceEdit>
                <CloudDeviceTimeChanger ref={this.timeChanger} ></CloudDeviceTimeChanger>
            </HomeLayout>
        );
    }

    componentDidMount() {
        console.log("CloudDeviceIndex::componentDidMount");
        this.reload();
    }

    async reload() {
        let data = await cloudDeivceApi.list() as any[];
        console.log("请求到的数据是：", data);
        data.forEach(element => { element.key = Math.random() });
        this.setState({ itemList: data });
    }

    deleteItem(item: any) {
        const that = this;
        Modal.confirm({
            title: Configure.Gl(1066,'警告'),
            icon: <ExclamationCircleOutlined />,
            maskClosable: true,
            content: Configure.Gl(1067,'你确定要删除 id = ') + item.id + ' code = ' + item.code + ' ( ' + item.name + ' ) ？',
            onOk() {
                cloudDeivceApi.delete(item.id).then(d => that.reload());
            }
        });
    }

}




 