import { consoleApi } from '../../util/http';
import { ApiBase } from '../api';
import Configure from '../Configure';

class CloudMqApi extends ApiBase {
    
    create(item: any) {
        return consoleApi.post({
            path: 'cloud/mq/v2/create',
            param: item,
            title: Configure.Gl(1660,'新建MQ')
        });
    }

    update(item: any) {
        return consoleApi.post({
            path: 'cloud/mq/v2/update',
            param: item,
            title: Configure.Gl(1661,'修改MQ')
        });
    }

    delete(code: string) {
        return consoleApi.get({
            path: 'cloud/mq/v2/delete?code='+code,
            title: Configure.Gl(1662,"删除MQ"),
            quiet: true
        });
    }

    list(query: any) {
        return consoleApi.get({
            path: 'cloud/mq/v2/list',
            title: Configure.Gl(1663,"列出MQ"),
            param: query,
            quiet: true
        });
    }

}

export const cloudMqApi: CloudMqApi = new CloudMqApi();