import React, { RefObject } from 'react';
import { Button, Table, Space} from 'antd';
import { HomeLayout } from '../../../layout/HomeLayout';
import { RoutePath } from '../../../route/path';
import { FormInstance } from 'antd/lib/form';
import { StdItemPage } from '../../../part/StdItemPage';
import { TablePaginationConfig, ColumnsType } from 'antd/lib/table/Table';
import { formatDate } from '../../../util/toolbox';
import { Key, TableCurrentDataSource } from 'antd/lib/table/interface';
import { SorterResult } from 'antd/es/table/interface';
import RebateEdit from './RebateEdit';
import { RouteComponentProps } from 'react-router';
import Search from 'antd/lib/input/Search';
import { rebateApi } from '../../../api/console/gm.rebate';
import Configure from '../../../api/Configure';

export default class RebateApproveIndex extends StdItemPage<any> {
    formRef = React.createRef<FormInstance>();
    private editor: RefObject<RebateEdit>;
    
    constructor(props: RouteComponentProps) {
        super(props);
        this.editor = React.createRef();
    }

    state = {
        itemTotal: undefined,
        queryPagination: {
            page: 1,
            pageSize: 10
        },
        itemList: [],
        queryFilter: {viewAll:true}
    }

    getCols(): ColumnsType<any> {
        return [
            {
                title: Configure.Gl(1118,'id'),
                dataIndex: ['gmRebateEntity','id'],
                width: 80,
            },
            {
                title: Configure.Gl(1212,'类型'),
                dataIndex: ['gmRebateEntity','type'],
                width: 80,
                render: (value: any) => value === 1 ? Configure.Gl(1275,"单日累计充值") : Configure.Gl(1276,"累计充值")
            },
            {
                title: Configure.Gl(1124,'标题'),
                dataIndex: ['gmRebateEntity','title'],
                width: 240,
            },
            {
                title: Configure.Gl(1088,'状态'),
                dataIndex: ['gmRebateEntity','status'],
                width: 80,
                render: (value: any) => value === 1 ? Configure.Gl(1201,"未审批") : value === 2 ? Configure.Gl(1202,"同意") : Configure.Gl(1203,"拒绝")
            },
            {
                title: Configure.Gl(1057,'操作'),
                dataIndex: ['gmRebateEntity','status'],
                width: 300,
                render: (value: any, record: any, index: number) => {
                    return (<Space>
                        <div style={{display : value === 1? "block": "none"}}>
                            <Button type="primary" onClick={() => this.doAccept(record)}>{Configure.Gl(1202,"同意")}</Button>
                            <Button danger style={{margin:'0 8px'}} onClick={() => this.doRefuse(record)}>{Configure.Gl(1203,"拒绝")}</Button>
                        </div>
                        <Button type="default" onClick={() => {
                            let master = Configure.Gl(1277,"发送玩家: ");
                            let masters = record.gmRebateTars as any[];
                            masters.forEach(v => master += v.masterIdHex + "  " + v.name + "  " + v.srvCode + "\n");
                            let previewContent = `${master}发送奖励: ${record.gmRebateEntity.rewardDesc}\n邮件标题: ${record.gmRebateEntity.title}\n邮件正文: ${record.gmRebateEntity.content}\n`;
                            alert(previewContent);
                        }}>{Configure.Gl(1204,"查看详情")}</Button>
                    </Space>);
                },
            },
            {
                title: Configure.Gl(1279,'玩家信息'),
                dataIndex: 'gmRebateTars',
                width: 240,
                render: (value: any[]) => value[0].masterIdHex + "\n" + value[0].name + "\n" + value[0].srvCode,
            },
            {
                title: Configure.Gl(1205,'提交人用户名'),
                width: 80,
                dataIndex: ['gmRebateEntity','submitUsername'],
            },
            {
                title: Configure.Gl(1206,'提交人昵称'),
                width: 120,
                dataIndex: ['gmRebateEntity','submitNickname'],
            },
            {
                title: Configure.Gl(1207,'提交时间'),
                width: 120,
                dataIndex: ['gmRebateEntity','submitTime'],
                render: (v, r) => formatDate(v)
            },
            {
                title: Configure.Gl(1208,'审核人用户名'),
                width: 80,
                dataIndex: ['gmRebateEntity','approveUsername'],
            },
            {
                title: Configure.Gl(1209,'审核人昵称'),
                width: 120,
                dataIndex: ['gmRebateEntity','approveNickname'],
            },
            {
                title: Configure.Gl(1210,'审核时间'),
                width: 120,
                dataIndex: ['gmRebateEntity','approveTime'],
                render: (v, r) => formatDate(v)
            },
            {
                title: Configure.Gl(1125,'内容'),
                width: 1200,
                dataIndex: ['gmRebateEntity','content'],
            }
        ];
    }

    render() {
        const { itemTotal, queryPagination } = this.state;
        const columns: ColumnsType<any> = this.getCols();
        const pagination: TablePaginationConfig = {
            showSizeChanger: true,
            showQuickJumper: true,
            defaultPageSize: queryPagination.pageSize,
            total: itemTotal
        };
        return (
            <HomeLayout path={RoutePath.REBATE_APPROVE_INDEX}>
                <Search placeholder={Configure.Gl(1211,"输入要搜索的提交人用户名")} onSearch={v=>{this.onSearch(v)}} style={{ width: 250 }} />
                <Search placeholder={Configure.Gl(1280,"输入要搜索的玩家id")} onSearch={v=>{this.onSearchMaster(v)}} style={{ width: 250 }} />
                <Table dataSource={this.state.itemList} columns={columns}
                pagination={pagination} scroll={{ x: this.getColsWidth(columns), y: 512 }}  onChange={(p, f, s, e) => { this.onPageChange(p, f, s, e) }}/>
                <RebateEdit ref={this.editor} reload={() => this.reload()}></RebateEdit>
            </HomeLayout>
        );
    }

    onSearch(v: any){
        let filter = v && v.length > 0?{viewAll: true, userName: v}: {viewAll: true}; 
        this.setState({queryFilter: filter}, ()=> {
            this.reload();
        });
    }

    onSearchMaster(v: any){
        let filter = v && v.length > 0?{viewAll: true, masterIdHex: v}: {viewAll: true}; 
        this.setState({queryFilter: filter}, ()=> {
            this.reload();
        });
    }

    onPageChange(pagination: TablePaginationConfig, filters: Record<string, Key[] | null>, sorter: SorterResult<any> | SorterResult<any>[], extra: TableCurrentDataSource<any>) {
        this.setState({queryPagination: {
            page: pagination.current,
            pageSize: pagination.pageSize
        }}, ()=>{
            this.reload();
        });
    }

    componentDidMount() {
        this.reload();
    }

    async reload() {
        const { queryPagination, queryFilter } = this.state; 
        const query = { ...queryPagination, ...queryFilter };
        console.log("请求参数为：",query);
        let data = await rebateApi.list(query) as any;
        console.log(Configure.Gl(1390,"请求到的数据是："), data);
        this.addKeyToData(data.records);
        this.setState({ itemList: data.records, itemTotal: data.total });
    }

    doAccept(item : any) {
        rebateApi.complete({status: 2,id: item.gmRebateEntity.id}).then(() => {
          this.reload();
        });
    }

    doRefuse(item : any) {
        rebateApi.complete({status: 3, id: item.gmRebateEntity.id}).then(() => {
          this.reload();
        });
    }
}